INSERT INTO site_text (key, value_en, value_id, is_placeholder) VALUES ('seo.home.title', 'Sunshine Facilities Group · Integrated facility services in Indonesia', 'Sunshine Facilities Group · Layanan fasilitas terpadu di Indonesia', false);
INSERT INTO site_text (key, value_en, value_id, is_placeholder) VALUES ('seo.home.description', 'Food, cleaning, MEP maintenance, security, environmental and workforce services for buildings across Indonesia.', 'Layanan makanan, kebersihan, perawatan MEP, keamanan, lingkungan, dan tenaga kerja untuk gedung di seluruh Indonesia.', false);
INSERT INTO site_text (key, value_en, value_id, is_placeholder) VALUES ('seo.services.title', 'Services', 'Layanan', false);
INSERT INTO site_text (key, value_en, value_id, is_placeholder) VALUES ('seo.services.description', 'Five business lines under one contract: food, digital, workforce, remote-site and facility management.', 'Lima lini layanan dalam satu kontrak: makanan, digital, tenaga kerja, site terpencil, dan manajemen fasilitas.', false);
INSERT INTO site_text (key, value_en, value_id, is_placeholder) VALUES ('seo.industries.title', 'Industries', 'Industri', false);
INSERT INTO site_text (key, value_en, value_id, is_placeholder) VALUES ('seo.industries.description', 'Facility services for healthcare, offices, retail, industrial and mining sites, hospitality, education and residential towers.', 'Layanan fasilitas untuk kesehatan, perkantoran, ritel, industri dan tambang, perhotelan, pendidikan, dan apartemen.', false);
INSERT INTO site_text (key, value_en, value_id, is_placeholder) VALUES ('seo.about.title', 'About Us', 'Tentang Kami', false);
INSERT INTO site_text (key, value_en, value_id, is_placeholder) VALUES ('seo.about.description', 'More than a decade of operational excellence, from healthcare catering in 2015 to integrated facility solutions. Part of Lippo Indonesia.', 'Lebih dari satu dekade keunggulan operasional, dari katering rumah sakit pada 2015 hingga solusi fasilitas terpadu. Bagian dari Lippo Indonesia.', false);
INSERT INTO site_text (key, value_en, value_id, is_placeholder) VALUES ('seo.careers.title', 'Careers', 'Karier', false);
INSERT INTO site_text (key, value_en, value_id, is_placeholder) VALUES ('seo.careers.description', 'Join over 1,000 people across 18+ cities keeping hospitals, offices, malls and remote sites running.', 'Bergabunglah dengan lebih dari 1.000 orang di 18+ kota yang menjaga rumah sakit, kantor, mal, dan site terpencil tetap berjalan.', false);
INSERT INTO site_text (key, value_en, value_id, is_placeholder) VALUES ('seo.contact.title', 'Contact & Request a Quotation', 'Kontak & Minta Penawaran', false);
INSERT INTO site_text (key, value_en, value_id, is_placeholder) VALUES ('seo.contact.description', 'Tell us about your building. We arrange a site survey and send an itemised proposal, usually within one working day.', 'Ceritakan tentang gedung Anda. Kami menjadwalkan survei lokasi dan mengirim proposal terperinci, biasanya dalam satu hari kerja.', false);
INSERT INTO page_sections (id, page, section, title_en, title_id, body_en, body_id, image_id, is_placeholder, sort) VALUES ('01a160e8-5066-74c6-9b8f-7e0b709a40bd', 'home', 'hero', 'Clean, well-run buildings.', 'Gedung bersih dan terkelola.', 'Sunshine Facilities Group runs food, cleaning, maintenance, security and workforce services for buildings across Indonesia: one partner, one team on site, one report.', 'Sunshine Facilities Group menangani layanan makanan, kebersihan, perawatan, keamanan, dan tenaga kerja untuk gedung di seluruh Indonesia: satu mitra, satu tim di lokasi, satu laporan.', NULL, false, 0);
INSERT INTO page_sections (id, page, section, title_en, title_id, body_en, body_id, image_id, is_placeholder, sort) VALUES ('01a160e8-5067-7791-8866-58bcbd196f7e', 'home', 'services', 'Five business lines, one team you can call.', 'Lima lini layanan, satu tim yang bisa Anda hubungi.', 'Take one service or combine several. Either way you get a single contract, a single site lead and a single monthly report.', 'Pilih satu layanan atau gabungkan beberapa. Anda tetap mendapat satu kontrak, satu penanggung jawab lokasi, dan satu laporan bulanan.', NULL, false, 1);
INSERT INTO page_sections (id, page, section, title_en, title_id, body_en, body_id, image_id, is_placeholder, sort) VALUES ('01a160e8-5068-7d73-9034-26d9b5256db8', 'home', 'why', 'You see what was done, by whom, and when.', 'Anda tahu apa yang dikerjakan, oleh siapa, dan kapan.', '', '', NULL, false, 2);
INSERT INTO page_sections (id, page, section, title_en, title_id, body_en, body_id, image_id, is_placeholder, sort) VALUES ('01a160e8-5069-77d1-bf7e-98661b8c473c', 'home', 'wo_before', 'Cleaner wiping a counter before the inspection', 'Petugas membersihkan meja sebelum inspeksi', '', '', (SELECT id FROM media WHERE slug = 'photo/cleaning'), false, 3);
INSERT INTO page_sections (id, page, section, title_en, title_id, body_en, body_id, image_id, is_placeholder, sort) VALUES ('01a160e8-506a-7ebc-b00b-239a84d7b86b', 'home', 'wo_after', 'Lobby floor after machine scrubbing', 'Lantai lobi setelah dibersihkan dengan mesin', '', '', (SELECT id FROM media WHERE slug = 'photo/lobby-cleaning'), false, 4);
INSERT INTO page_sections (id, page, section, title_en, title_id, body_en, body_id, image_id, is_placeholder, sort) VALUES ('01a160e8-506b-7f1c-9272-7ec8ea10abac', 'home', 'certificates', 'Audited food safety and hygiene.', 'Keamanan pangan dan higiene yang diaudit.', 'Our kitchens and processes are audited by independent bodies. Click a certificate to view it.', 'Dapur dan proses kami diaudit oleh lembaga independen. Klik sertifikat untuk melihatnya.', NULL, false, 5);
INSERT INTO page_sections (id, page, section, title_en, title_id, body_en, body_id, image_id, is_placeholder, sort) VALUES ('01a160e8-506c-7020-a06c-426f63600225', 'home', 'testimonials', 'What clients say', 'Kata klien kami', '', '', NULL, false, 6);
INSERT INTO page_sections (id, page, section, title_en, title_id, body_en, body_id, image_id, is_placeholder, sort) VALUES ('01a160e8-506d-7db4-9b8f-e22fb4b2a8b4', 'home', 'quote', 'Tell us about your building.', 'Ceritakan tentang gedung Anda.', 'We will arrange a site survey and send an itemised proposal. Prefer to talk first? Message us on WhatsApp.', 'Kami akan menjadwalkan survei lokasi dan mengirim proposal terperinci. Ingin bicara dulu? Hubungi kami lewat WhatsApp.', NULL, false, 7);
INSERT INTO page_sections (id, page, section, title_en, title_id, body_en, body_id, image_id, is_placeholder, sort) VALUES ('01a160e8-506e-77ae-8bfc-9088ddce721e', 'services', 'hero', 'Five business lines. One partner on site.', 'Lima lini layanan. Satu mitra di lokasi.', 'Sunshine started in healthcare catering in 2015. Today we deliver food, facility, workforce, remote-site and digital services through one contract, one site lead and one monthly report.', 'Sunshine berawal dari katering rumah sakit pada 2015. Kini kami menghadirkan layanan makanan, fasilitas, tenaga kerja, site terpencil, dan digital melalui satu kontrak, satu penanggung jawab lokasi, dan satu laporan bulanan.', NULL, false, 8);
INSERT INTO page_sections (id, page, section, title_en, title_id, body_en, body_id, image_id, is_placeholder, sort) VALUES ('01a160e8-506f-775e-8ad3-730efeb75b68', 'services', 'benefits', 'Take one line or combine several.', 'Pilih satu lini atau gabungkan beberapa.', '', '', NULL, false, 9);
INSERT INTO page_sections (id, page, section, title_en, title_id, body_en, body_id, image_id, is_placeholder, sort) VALUES ('01a160e8-5070-7a8d-bd31-a23ca67a1a78', 'services', 'cta', 'Not sure which services your building needs?', 'Belum yakin layanan apa yang dibutuhkan gedung Anda?', 'We will survey your site with your team and send an itemised proposal.', 'Kami akan menyurvei lokasi bersama tim Anda dan mengirim proposal terperinci.', NULL, false, 10);
INSERT INTO page_sections (id, page, section, title_en, title_id, body_en, body_id, image_id, is_placeholder, sort) VALUES ('01a160e8-5071-7704-8bc6-c9ad9a22d5d7', 'service_detail', 'map', 'Where we deliver', 'Jangkauan kami', 'Five distribution hubs and 60 retail distribution points connect our kitchens and stores to sites across Indonesia, including Timika lowland and highland.', 'Lima hub distribusi dan 60 titik distribusi ritel menghubungkan dapur dan gudang kami ke lokasi di seluruh Indonesia, termasuk Timika dataran rendah dan dataran tinggi.', NULL, false, 11);
INSERT INTO page_sections (id, page, section, title_en, title_id, body_en, body_id, image_id, is_placeholder, sort) VALUES ('01a160e8-5072-7fe7-aedc-a3fb54a964d2', 'service_detail', 'certificates', 'Certified food safety', 'Keamanan pangan bersertifikat', '', '', NULL, false, 12);
INSERT INTO page_sections (id, page, section, title_en, title_id, body_en, body_id, image_id, is_placeholder, sort) VALUES ('01a160e8-5073-7ffc-a061-4f3d0e1acd52', 'service_detail', 'proof', 'Every job, on record.', 'Setiap pekerjaan, tercatat.', 'Whichever line you choose, the work is logged in our field app so your team can check what was done, by whom and when.', 'Lini apa pun yang Anda pilih, pekerjaan dicatat di aplikasi lapangan kami sehingga tim Anda dapat memeriksa apa yang dikerjakan, oleh siapa, dan kapan.', NULL, false, 13);
INSERT INTO page_sections (id, page, section, title_en, title_id, body_en, body_id, image_id, is_placeholder, sort) VALUES ('01a160e8-5074-7ef4-9e48-d7f238a7a54e', 'service_detail', 'industries', 'Industries we serve with this line', 'Industri yang kami layani dengan lini ini', '', '', NULL, false, 14);
INSERT INTO page_sections (id, page, section, title_en, title_id, body_en, body_id, image_id, is_placeholder, sort) VALUES ('01a160e8-5075-7c4c-9aa0-9fcd0fe1b8c3', 'service_detail', 'cta', 'Tell us about your site.', 'Ceritakan tentang lokasi Anda.', 'We will arrange a survey and send an itemised proposal for this service.', 'Kami akan menjadwalkan survei dan mengirim proposal terperinci untuk layanan ini.', NULL, false, 15);
INSERT INTO page_sections (id, page, section, title_en, title_id, body_en, body_id, image_id, is_placeholder, sort) VALUES ('01a160e8-5076-797b-8e96-ab940a25ca7c', 'industries', 'hero', 'Built around how each kind of building runs.', 'Disesuaikan dengan cara setiap gedung beroperasi.', 'A hospital kitchen and a mining camp canteen have different rules. Our experience across the Lippo ecosystem and beyond lets us staff and train for the site you have.', 'Dapur rumah sakit dan kantin site tambang punya aturan berbeda. Pengalaman kami di ekosistem Lippo dan di luarnya membuat kami bisa menyiapkan dan melatih tim sesuai lokasi Anda.', NULL, false, 16);
INSERT INTO page_sections (id, page, section, title_en, title_id, body_en, body_id, image_id, is_placeholder, sort) VALUES ('01a160e8-5077-75f9-be80-d18785e95953', 'industries', 'cta', 'Your sector is not listed?', 'Sektor Anda tidak tercantum?', 'We also support financial services, EPC and institutional sites. Tell us what your site needs.', 'Kami juga mendukung jasa keuangan, EPC, dan lokasi institusi. Ceritakan kebutuhan lokasi Anda.', NULL, false, 17);
INSERT INTO page_sections (id, page, section, title_en, title_id, body_en, body_id, image_id, is_placeholder, sort) VALUES ('01a160e8-5078-7efe-9127-2377d9b3826f', 'about', 'hero', 'More than a decade of operational excellence.', 'Lebih dari satu dekade keunggulan operasional.', 'For over 10 years, Sunshine has built a strong track record in delivering reliable operational services across Indonesia, earning the trust of leading organizations through food service excellence, operational expertise, and a commitment to quality.', 'Selama lebih dari 10 tahun, Sunshine membangun rekam jejak yang kuat dalam menghadirkan layanan operasional yang andal di seluruh Indonesia, dipercaya organisasi terkemuka berkat keunggulan layanan makanan, keahlian operasional, dan komitmen terhadap kualitas.', NULL, false, 18);
INSERT INTO page_sections (id, page, section, title_en, title_id, body_en, body_id, image_id, is_placeholder, sort) VALUES ('01a160e8-5079-7932-ac3b-3d8f34c5ab2f', 'about', 'poster', '2015', '2015', 'Established as Sunshine Food Group, with a focus on healthcare catering.', 'Didirikan sebagai Sunshine Food Group, berfokus pada katering rumah sakit.', (SELECT id FROM media WHERE slug = 'photo/kitchen'), false, 19);
INSERT INTO page_sections (id, page, section, title_en, title_id, body_en, body_id, image_id, is_placeholder, sort) VALUES ('01a160e8-507a-7320-848f-3e8d40c039d1', 'about', 'story', 'One integrated solution partner.', 'Satu mitra solusi terpadu.', 'Building on this foundation, we have evolved into Sunshine Facility Group, an integrated facility solutions partner delivering Food Services, Technical Services, Soft Services, and Supply Chain Solutions through one trusted platform.
INSERT INTO page_sections (id, page, section, title_en, title_id, body_en, body_id, image_id, is_placeholder, sort) VALUES ('01a160e8-507b-73b6-9872-25e68be729ef', 'about', 'journey', 'From food expertise to integrated facility solutions.', 'Dari keahlian pangan menuju solusi fasilitas terpadu.', '', '', NULL, false, 21);
INSERT INTO page_sections (id, page, section, title_en, title_id, body_en, body_id, image_id, is_placeholder, sort) VALUES ('01a160e8-507c-76a3-97ce-aa6a5a933e86', 'about', 'vision_mission', 'Vision & mission', 'Visi & misi', '', '', NULL, true, 22);
INSERT INTO page_sections (id, page, section, title_en, title_id, body_en, body_id, image_id, is_placeholder, sort) VALUES ('01a160e8-507d-703b-8238-6c3491cc97b6', 'about', 'vision', '', '', 'To be Indonesia’s most trusted integrated facility solutions partner.', 'Menjadi mitra solusi fasilitas terpadu paling tepercaya di Indonesia.', NULL, true, 23);
INSERT INTO page_sections (id, page, section, title_en, title_id, body_en, body_id, image_id, is_placeholder, sort) VALUES ('01a160e8-507e-7ed6-9df8-40ffceac4652', 'about', 'values', 'What we stand for', 'Nilai kami', '', '', NULL, false, 24);
INSERT INTO page_sections (id, page, section, title_en, title_id, body_en, body_id, image_id, is_placeholder, sort) VALUES ('01a160e8-507f-770d-bc7e-efa1854f4424', 'about', 'ecosystem', 'Powered by one of Indonesia’s strongest business ecosystems.', 'Didukung salah satu ekosistem bisnis terkuat di Indonesia.', 'Part of Lippo Indonesia. Built for integrated operations. Our experience across many industries helps us understand diverse operational needs.', 'Bagian dari Lippo Indonesia. Dibangun untuk operasional terpadu. Pengalaman kami di banyak industri membantu kami memahami beragam kebutuhan operasional.', NULL, false, 25);
INSERT INTO page_sections (id, page, section, title_en, title_id, body_en, body_id, image_id, is_placeholder, sort) VALUES ('01a160e8-5080-71f7-84db-ddeb42520a44', 'about', 'certificates', 'Certifications', 'Sertifikasi', '', '', NULL, false, 26);
INSERT INTO page_sections (id, page, section, title_en, title_id, body_en, body_id, image_id, is_placeholder, sort) VALUES ('01a160e8-5081-7dfb-a65f-73cd49e02d89', 'about', 'management', 'Management', 'Manajemen', '', '', NULL, false, 27);
INSERT INTO page_sections (id, page, section, title_en, title_id, body_en, body_id, image_id, is_placeholder, sort) VALUES ('01a160e8-5082-78b5-9975-42a676ce5211', 'about', 'cta', 'Let’s talk about your site, or your career.', 'Mari bicara tentang lokasi Anda, atau karier Anda.', '', '', NULL, false, 28);
INSERT INTO page_sections (id, page, section, title_en, title_id, body_en, body_id, image_id, is_placeholder, sort) VALUES ('01a160e8-5083-7a5d-86d3-d6d422605396', 'careers', 'hero', 'Your operations. Our people.', 'Operasional Anda. Orang-orang kami.', 'Over 1,000 people across 18+ cities keep hospitals, offices, malls and remote sites running. Join them.', 'Lebih dari 1.000 orang di 18+ kota menjaga rumah sakit, kantor, mal, dan site terpencil tetap berjalan. Bergabunglah bersama mereka.', (SELECT id FROM media WHERE slug = 'photo/team'), false, 29);
INSERT INTO page_sections (id, page, section, title_en, title_id, body_en, body_id, image_id, is_placeholder, sort) VALUES ('01a160e8-5084-7261-96a4-9ecf30d87a78', 'careers', 'reasons', 'Why people stay with Sunshine', 'Mengapa orang bertahan di Sunshine', '', '', NULL, false, 30);
INSERT INTO page_sections (id, page, section, title_en, title_id, body_en, body_id, image_id, is_placeholder, sort) VALUES ('01a160e8-5085-7c79-a966-e57cd586d776', 'careers', 'openings', 'Open positions', 'Lowongan', '', '', NULL, false, 31);
INSERT INTO page_sections (id, page, section, title_en, title_id, body_en, body_id, image_id, is_placeholder, sort) VALUES ('01a160e8-5086-7b5d-9f07-baa6a1f40b91', 'careers', 'apply', 'Apply now', 'Lamar sekarang', 'Send your details and CV. Our recruitment team replies within five working days. Not seeing your role? Choose “Open application”.', 'Kirim data diri dan CV Anda. Tim rekrutmen kami membalas dalam lima hari kerja. Posisi Anda tidak ada? Pilih “Lamaran terbuka”.', NULL, false, 32);
INSERT INTO page_sections (id, page, section, title_en, title_id, body_en, body_id, image_id, is_placeholder, sort) VALUES ('01a160e8-5087-7441-b0b3-add6ad66438f', 'contact', 'hero', 'Request a quotation.', 'Minta penawaran.', 'Tell us about your building. We will arrange a site survey and send an itemised proposal, usually within one working day.', 'Ceritakan tentang gedung Anda. Kami akan menjadwalkan survei lokasi dan mengirim proposal terperinci, biasanya dalam satu hari kerja.', NULL, false, 33);
