INSERT INTO service_lines (id, key, sort, title_en, title_id, short_en, short_id, label_en, label_id, summary_en, summary_id, description_en, description_id, lead_en, lead_id, color_base, color_ink, color_shade, color_on_ink, color_label, mark_id, photo_id, show_map, show_certs, map_image_id) VALUES ('01a160e8-5089-7f07-97da-89acaf328d58', 'food', 1, 'Food Services', 'Layanan Makanan', 'Food', 'Makanan', 'Food Services', 'Layanan Makanan', 'Hospital, corporate and industrial catering, from kitchen design to daily service.', 'Katering rumah sakit, korporat, dan industri, dari desain dapur hingga layanan harian.', 'End-to-end food service that is safe, nutritious and efficient, from kitchen design to daily service in hospitals, offices and industrial sites.', 'Layanan makanan menyeluruh yang aman, bergizi, dan efisien, dari desain dapur hingga layanan harian di rumah sakit, kantor, dan kawasan industri.', 'End-to-end food service solutions: safe, nutritious and efficient food service across industries.', 'Solusi layanan makanan menyeluruh: aman, bergizi, dan efisien di berbagai industri.', '#EA2915', '#C6241C', '#C6241C', '#FFFFFF', '#C6241C', (SELECT id FROM media WHERE slug = 'brand/sg-food'), (SELECT id FROM media WHERE slug = 'photo/kitchen'), false, true, NULL);
