INSERT INTO service_groups (id, line_id, title_en, title_id, body_en, body_id, items_en, items_id, sort) VALUES ('01a160e8-50c6-7dc9-aa54-77439d6c8c9f', (SELECT id FROM service_lines WHERE key = 'workforce'), 'Training and Development', 'Pelatihan dan Pengembangan', 'Role-specific training, service standards, safety protocols, and continuous capability development.', 'Pelatihan sesuai peran, standar layanan, protokol keselamatan, dan pengembangan kemampuan berkelanjutan.', '', '', 2);
INSERT INTO service_groups (id, line_id, title_en, title_id, body_en, body_id, items_en, items_id, sort) VALUES ('01a160e8-50c7-7035-a9f5-d47a9dc08f76', (SELECT id FROM service_lines WHERE key = 'workforce'), 'Workforce Management', 'Manajemen Tenaga Kerja', 'Managing attendance, shifts, staffing requirements, documentation, and day-to-day workforce administration.', 'Mengelola absensi, shift, kebutuhan staf, dokumentasi, dan administrasi tenaga kerja harian.', '', '', 3);
INSERT INTO service_groups (id, line_id, title_en, title_id, body_en, body_id, items_en, items_id, sort) VALUES ('01a160e8-50c8-7fbd-8f3b-5cf2b4351823', (SELECT id FROM service_lines WHERE key = 'workforce'), 'Performance Management', 'Manajemen Kinerja', 'Monitoring workforce performance through defined KPIs, regular evaluations, and continuous improvement programs.', 'Memantau kinerja tenaga kerja melalui KPI, evaluasi rutin, dan program perbaikan berkelanjutan.', '', '', 4);
INSERT INTO service_groups (id, line_id, title_en, title_id, body_en, body_id, items_en, items_id, sort) VALUES ('01a160e8-50c9-77a5-b8a4-9b27b8e6a41a', (SELECT id FROM service_lines WHERE key = 'workforce'), 'Payroll and Administration', 'Penggajian dan Administrasi', 'Streamlining payroll, employment documentation, and workforce administration for greater accuracy and operational efficiency.', 'Menyederhanakan penggajian, dokumen kepegawaian, dan administrasi tenaga kerja agar lebih akurat dan efisien.', '', '', 5);
INSERT INTO service_groups (id, line_id, title_en, title_id, body_en, body_id, items_en, items_id, sort) VALUES ('01a160e8-50ca-784b-9e48-f2465cd8be78', (SELECT id FROM service_lines WHERE key = 'workforce'), 'Digital Workforce Management', 'Manajemen Tenaga Kerja Digital', 'Technology-enabled visibility across attendance, scheduling, workforce performance, and operational reporting.', 'Visibilitas berbasis teknologi atas absensi, penjadwalan, kinerja tenaga kerja, dan pelaporan operasional.', '', '', 6);
