INSERT INTO content_items (id, list_key, icon, title_en, title_id, body_en, body_id, meta_en, meta_id, color, sort, is_placeholder) VALUES ('01a160e8-5115-7f71-a8a0-dad5ccd18b03', 'home_why', 'identification-badge', 'Trained, supervised staff', 'Staf terlatih dan diawasi', 'Every crew member is trained for the site before day one, and a supervisor checks the work on every shift.', 'Setiap anggota tim dilatih sesuai lokasi sebelum mulai bertugas, dan supervisor memeriksa pekerjaan di setiap shift.', '', '', '', 1, false);
INSERT INTO content_items (id, list_key, icon, title_en, title_id, body_en, body_id, meta_en, meta_id, color, sort, is_placeholder) VALUES ('01a160e8-5116-7266-bc39-8fb6b70deaa7', 'home_why', 'calendar-check', 'Scheduled preventive maintenance', 'Perawatan preventif terjadwal', 'Equipment is serviced on a calendar we agree with you, so breakdowns become the exception.', 'Peralatan dirawat sesuai jadwal yang kami sepakati bersama, sehingga kerusakan jarang terjadi.', '', '', '', 2, false);
INSERT INTO content_items (id, list_key, icon, title_en, title_id, body_en, body_id, meta_en, meta_id, color, sort, is_placeholder) VALUES ('01a160e8-5117-78d2-aae0-b30acded0458', 'home_why', 'device-mobile-camera', 'Digital reporting & proof of work', 'Laporan digital & bukti kerja', 'Each job is logged in our mobile app with before and after photos, a timestamp and a digital sign-off. No paper.', 'Setiap pekerjaan dicatat di aplikasi kami dengan foto sebelum dan sesudah, waktu, dan tanda tangan digital. Tanpa kertas.', '', '', '', 3, false);
INSERT INTO content_items (id, list_key, icon, title_en, title_id, body_en, body_id, meta_en, meta_id, color, sort, is_placeholder) VALUES ('01a160e8-5118-7eca-a9de-5754cf82da8b', 'home_why', 'phone-call', '24/7 response', 'Respons 24/7', 'One number, answered day and night, with escalation to your site lead.', 'Satu nomor yang dijawab siang dan malam, dengan eskalasi ke penanggung jawab lokasi Anda.', '', '', '', 4, false);
INSERT INTO content_items (id, list_key, icon, title_en, title_id, body_en, body_id, meta_en, meta_id, color, sort, is_placeholder) VALUES ('01a160e8-5119-7108-9554-14f81ce2b2f8', 'services_benefits', 'file-text', 'One contract', 'Satu kontrak', 'All services you choose sit under one agreement, with one invoice.', 'Semua layanan yang Anda pilih berada dalam satu perjanjian dengan satu tagihan.', '', '', '', 1, false);
INSERT INTO content_items (id, list_key, icon, title_en, title_id, body_en, body_id, meta_en, meta_id, color, sort, is_placeholder) VALUES ('01a160e8-511a-7261-a48b-0ad56961c9f5', 'services_benefits', 'user-circle-check', 'One site lead', 'Satu penanggung jawab', 'A named person on site who answers for every service and every shift.', 'Satu orang di lokasi yang bertanggung jawab atas setiap layanan dan setiap shift.', '', '', '', 2, false);
INSERT INTO content_items (id, list_key, icon, title_en, title_id, body_en, body_id, meta_en, meta_id, color, sort, is_placeholder) VALUES ('01a160e8-511b-770e-85a4-f950db000fa0', 'services_benefits', 'chart-line-up', 'One monthly report', 'Satu laporan bulanan', 'KPIs for every line in one review, with each job traceable in our app.', 'KPI setiap lini dalam satu evaluasi, dengan setiap pekerjaan terlacak di aplikasi kami.', '', '', '', 3, false);
INSERT INTO content_items (id, list_key, icon, title_en, title_id, body_en, body_id, meta_en, meta_id, color, sort, is_placeholder) VALUES ('01a160e8-511c-77f6-95bd-7817fe165d34', 'service_proof', 'camera', 'Before and after photos for each task', 'Foto sebelum dan sesudah untuk setiap tugas', '', '', '', '', '', 1, false);
INSERT INTO content_items (id, list_key, icon, title_en, title_id, body_en, body_id, meta_en, meta_id, color, sort, is_placeholder) VALUES ('01a160e8-511d-717a-8e75-3bf65e39b482', 'service_proof', 'clock', 'Start and finish time with location', 'Waktu mulai dan selesai beserta lokasi', '', '', '', '', '', 2, false);
