INSERT INTO content_items (id, list_key, icon, title_en, title_id, body_en, body_id, meta_en, meta_id, color, sort, is_placeholder) VALUES ('01a160e8-511f-7000-989d-ad69c0c92b79', 'service_proof', 'chart-line-up', 'Monthly KPI review with your site lead', 'Evaluasi KPI bulanan bersama penanggung jawab lokasi', '', '', '', '', '', 4, false);
INSERT INTO content_items (id, list_key, icon, title_en, title_id, body_en, body_id, meta_en, meta_id, color, sort, is_placeholder) VALUES ('01a160e8-5120-7c0d-9390-5fef753ba1f9', 'careers_reasons', 'graduation-cap', 'Training before day one', 'Pelatihan sebelum mulai bertugas', 'Role-specific training, service standards and safety protocols, then continuous development.', 'Pelatihan sesuai peran, standar layanan, dan protokol keselamatan, lalu pengembangan berkelanjutan.', '', '', '', 1, false);
INSERT INTO content_items (id, list_key, icon, title_en, title_id, body_en, body_id, meta_en, meta_id, color, sort, is_placeholder) VALUES ('01a160e8-5121-7c2b-bc0c-d2ddc9a44fbd', 'careers_reasons', 'path', 'Room to grow', 'Ruang untuk berkembang', 'Move between sites, sectors and service lines as your skills grow.', 'Pindah antar lokasi, sektor, dan lini layanan seiring berkembangnya kemampuan Anda.', '', '', '', 2, false);
INSERT INTO content_items (id, list_key, icon, title_en, title_id, body_en, body_id, meta_en, meta_id, color, sort, is_placeholder) VALUES ('01a160e8-5122-7411-863b-e285e795a0d1', 'careers_reasons', 'device-mobile', 'Digital tools', 'Alat kerja digital', 'Attendance, schedules and work orders in one app, so less time goes on paperwork.', 'Absensi, jadwal, dan perintah kerja dalam satu aplikasi, sehingga lebih sedikit waktu untuk administrasi.', '', '', '', 3, false);
INSERT INTO content_items (id, list_key, icon, title_en, title_id, body_en, body_id, meta_en, meta_id, color, sort, is_placeholder) VALUES ('01a160e8-5123-7446-86c3-ea358d34f964', 'careers_reasons', 'buildings', 'Part of Lippo Indonesia', 'Bagian dari Lippo Indonesia', 'Stable work inside one of Indonesia’s largest business ecosystems.', 'Pekerjaan yang stabil di dalam salah satu ekosistem bisnis terbesar di Indonesia.', '', '', '', 4, false);
